const fs = require('fs');
const path = require('path');
const os = require('os');

const AGENTS_DIR = '/Users/kemuniagent/.openclaw/agents';
const STATE_FILE = '/Users/kemuniagent/.openclaw/logs/model-switch-watcher-state.json';

// Load state
let state = {};
try {
  state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
} catch(e) {}

// Collect model_change events per agent
const agentDirs = fs.readdirSync(AGENTS_DIR).filter(d => {
  try { return fs.statSync(path.join(AGENTS_DIR, d)).isDirectory(); } catch(e) { return false; }
});

const allSwitches = [];
const newState = Object.assign({}, state);

for (const agent of agentDirs) {
  const sessionsDir = path.join(AGENTS_DIR, agent, 'sessions');
  if (!fs.existsSync(sessionsDir)) continue;

  const files = fs.readdirSync(sessionsDir).filter(f => f.endsWith('.jsonl'));
  const events = [];

  for (const file of files) {
    const fpath = path.join(sessionsDir, file);
    let content;
    try { content = fs.readFileSync(fpath, 'utf8'); } catch(e) { continue; }
    for (const line of content.split('\n')) {
      if (!line.trim()) continue;
      try {
        const d = JSON.parse(line);
        if (d.type === 'model_change' && d.timestamp && d.provider && d.modelId) {
          events.push({ts: d.timestamp, model: d.provider + '/' + d.modelId});
        }
      } catch(e) {}
    }
  }

  if (!events.length) continue;
  events.sort((a,b) => a.ts.localeCompare(b.ts));

  const lastSeen = state[agent] || '';
  const knownEvents = events.filter(e => e.ts <= lastSeen);
  const newEvents = events.filter(e => e.ts > lastSeen);
  if (!newEvents.length) continue;

  let prevModel = knownEvents.length ? knownEvents[knownEvents.length-1].model : null;

  for (const ev of newEvents) {
    if (prevModel && prevModel !== ev.model) {
      const dt = new Date(ev.ts);
      const tsFmt = dt.toISOString().replace('T',' ').replace('.000Z',' UTC').replace(/\.\d+Z/, ' UTC');
      allSwitches.push({
        agent, from_model: prevModel, to_model: ev.model, timestamp: ev.ts, ts_fmt: tsFmt
      });
    }
    prevModel = ev.model;
    if (!newState[agent] || newState[agent] < ev.ts) newState[agent] = ev.ts;
  }
}

// Save state
try {
  fs.mkdirSync('/Users/kemuniagent/.openclaw/logs', {recursive: true});
  fs.writeFileSync(STATE_FILE, JSON.stringify(newState, null, 2));
} catch(e) {}

// Return one item per switch
if (!allSwitches.length) {
  return [{json: {switches: [], message: 'No new model switches'}}];
}

return allSwitches.map(s => ({json: s}));
